class Solution {
    public int findTargetSumWays(int[] nums, int target) {
        return dfs(nums, 0, target);
    }

    private int dfs(int[] nums, int i, int rest) {
        if (i == nums.length) {
            return rest == 0 ? 1 : 0;
        }
        int add = dfs(nums, i + 1, rest - nums[i]);
        int sub = dfs(nums, i + 1, rest + nums[i]);
        return add + sub;
    }
}

import java.util.*;

class Solution {
    public int findTargetSumWays(int[] nums, int target) {
        return dfs(nums, 0, target, new HashMap<>());
    }

    private int dfs(int[] nums, int i, int rest, Map<String, Integer> memo) {
        if (i == nums.length) {
            return rest == 0 ? 1 : 0;
        }
        String key = i + "," + rest;
        Integer cached = memo.get(key);
        if (cached != null) return cached;

        int ans = dfs(nums, i + 1, rest - nums[i], memo)
                + dfs(nums, i + 1, rest + nums[i], memo);
        memo.put(key, ans);
        return ans;
    }
}

class Solution {
    public int findTargetSumWays(int[] nums, int target) {
        int sum = 0;
        for (int num : nums) sum += num;

        int diff = sum + target;
        if (diff % 2 != 0) return 0;
        int p = diff / 2;
        if (p < 0 || p > sum) return 0;

        int[] dp = new int[p + 1];
        dp[0] = 1;
        for (int num : nums) {
            for (int j = p; j >= num; j--) {
                dp[j] += dp[j - num];
            }
        }
        return dp[p];
    }
}
